package in.terratech.vegmap;
import java.security.SecureRandom; import java.util.*; import java.util.concurrent.*;
import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import org.springframework.security.crypto.password.PasswordEncoder;
@RestController @RequestMapping("/api")
public class SecurityController {
 final Map<String,Seller> sellers=new ConcurrentHashMap<>(); final Map<String,String> otps=new ConcurrentHashMap<>(),sessions=new ConcurrentHashMap<>(); final Map<String,Long> expiry=new ConcurrentHashMap<>(); final SecureRandom rng=new SecureRandom(); final PasswordEncoder encoder;
 public SecurityController(PasswordEncoder e){encoder=e;}
 public static class Register {public String phone,name,password,location;}
 public static class Phone {public String phone;}
 public static class Verify {public String phone,otp;}
 public static class Login {public String phone,password;}
 public static class Location {public String location;public double latitude,longitude;}
 public static class Decision {public String decision;}
 @PostMapping("/auth/register") public Map<String,Object> register(@RequestBody Register r){if(r.phone==null||!r.phone.matches("\\+?[0-9]{10,15}")||r.name==null||r.name.isBlank()||r.password==null||r.password.length()<8||r.location==null||r.location.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter valid phone, name, location and password (8+ characters).");if(sellers.containsKey(r.phone))throw new ResponseStatusException(HttpStatus.CONFLICT,"Phone already registered.");Seller s=new Seller();s.phone=r.phone;s.name=r.name.trim();s.passwordHash=encoder.encode(r.password);s.location=r.location.trim();s.status="PENDING";sellers.put(s.phone,s);return Map.of("message","Account created. Verify phone and submit location, then wait for admin review.","status",s.status);}
 @PostMapping("/auth/request-otp") public Map<String,String> otp(@RequestBody Phone r){if(!sellers.containsKey(r.phone))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Register first.");String code=String.format("%06d",rng.nextInt(1000000));otps.put(r.phone,code);expiry.put(r.phone,System.currentTimeMillis()+300000);return Map.of("message","DEMO ONLY: no SMS provider connected; OTP is shown here.","demoOtp",code,"expiresInSeconds","300");}
 @PostMapping("/auth/verify-otp") public Map<String,String> verify(@RequestBody Verify r){if(!Objects.equals(otps.get(r.phone),r.otp)||expiry.getOrDefault(r.phone,0L)<System.currentTimeMillis())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"OTP invalid or expired.");sellers.get(r.phone).phoneVerified=true;otps.remove(r.phone);expiry.remove(r.phone);return Map.of("message","Phone verified.");}
 @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Login r){Seller s=sellers.get(r.phone);if(s==null||r.password==null||!encoder.matches(r.password,s.passwordHash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Incorrect phone or password.");if(!s.phoneVerified)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Verify phone first.");String t=UUID.randomUUID().toString();sessions.put(t,s.phone);return Map.of("token",t,"phone",s.phone,"name",s.name,"status",s.status);}
 @PostMapping("/location/submit") public Map<String,Object> location(@RequestHeader(value="X-VegMap-Token",required=false)String t,@RequestBody Location r){Seller s=auth(t);if(r.location==null||r.location.isBlank()||r.latitude < -90||r.latitude>90||r.longitude < -180||r.longitude>180)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter valid location and coordinates.");s.location=r.location;s.latitude=r.latitude;s.longitude=r.longitude;return publicSeller(s);}
 @GetMapping("/auth/me") public Map<String,Object> me(@RequestHeader(value="X-VegMap-Token",required=false)String t){return publicSeller(auth(t));}
 @PostMapping("/auth/logout") public Map<String,String> logout(@RequestHeader(value="X-VegMap-Token",required=false)String t){if(t!=null)sessions.remove(t);return Map.of("message","Logged out.");}
 @GetMapping("/admin/sellers") public List<Map<String,Object>> all(){return sellers.values().stream().map(this::publicSeller).toList();}
 @PostMapping("/admin/sellers/{phone}/decision") public Map<String,Object> decide(@PathVariable String phone,@RequestBody Decision d){Seller s=sellers.get(phone);if(s==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Seller not found.");if(!s.phoneVerified)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Phone must be verified first.");if(!"APPROVED".equalsIgnoreCase(d.decision)&&!"REJECTED".equalsIgnoreCase(d.decision))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Decision must be APPROVED or REJECTED.");s.status=d.decision.toUpperCase(Locale.ROOT);return publicSeller(s);}
 Seller auth(String t){String p=t==null?null:sessions.get(t);Seller s=p==null?null:sellers.get(p);if(s==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Please log in again.");return s;}
 public boolean approved(String t){return auth(t).status.equals("APPROVED");} public String owner(String t){return auth(t).phone;}
 Map<String,Object> publicSeller(Seller s){Map<String,Object> m=new LinkedHashMap<>();m.put("phone",s.phone);m.put("name",s.name);m.put("location",s.location);m.put("latitude",s.latitude);m.put("longitude",s.longitude);m.put("phoneVerified",s.phoneVerified);m.put("status",s.status);return m;}
}